const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const overlaps=(a,b)=>a.x<b.x+b.w+8&&a.x+a.w+8>b.x&&a.y<b.y+b.h+8&&a.y+a.h+8>b.y;
export function layoutLabels(items,width,height,active){const result=Array(items.length).fill(null),used=[];const order=items.map((_,i)=>i).sort((a,b)=>(b===active)-(a===active));for(const i of order){const item=items[i];if(!item.visible)continue;const {x,y}=item;const w=Math.min(item.w,width-16),h=Math.min(item.h,height-16);const candidates=[{x:x-w/2,y:y-h-24},{x:x-w/2,y:y+24},{x:x+24,y:y-h/2},{x:x-w-24,y:y-h/2}].map(p=>({x:clamp(p.x,8,width-w-8),y:clamp(p.y,8,height-h-8),w,h}));const chosen=candidates.find(r=>!used.some(o=>overlaps(r,o)));if(!chosen)continue;used.push(chosen);result[i]={...chosen,anchorX:x,anchorY:y,lineX:clamp(x,chosen.x,chosen.x+w),lineY:clamp(y,chosen.y,chosen.y+h)}}return result}
